(function(){
  var p=window.UMA_SUPPORT_LIBRARY_V31,cfg=window.AUTO_FACTOR_DATA;if(!p||!cfg)return;
  var by={};(cfg.skillCatalog||[]).forEach(function(s){by[s.name]=s});
  function aptitude(name){var m=String(name).match(/^(短距離|マイル|中距離|長距離|逃げ|先行|差し|追込)/);return m?m[1]:null}
  function guessSp(n,g){if(p.knownSp[n])return p.knownSp[n];if(g==='gold')return 180;if(/(短距離|マイル|中距離|長距離)(直線|コーナー)○$/.test(n))return 100;if(/(逃げ|先行|差し|追込)(直線|コーナー)○$/.test(n))return 130;if(/○$/.test(n))return 100;if(/(ためらい|けん制|焦り|駆け引き|束縛|ささやき|布石)/.test(n))return 130;return 160}
  function guessEval(n,g){if(g==='gold')return 508;if(/○$/.test(n)&&/(右回り|左回り|季節|レース場|良バ場|道悪|根幹距離|非根幹距離|一匹狼|対抗意識)/.test(n))return 85;if(/(ためらい|けん制|焦り|駆け引き|束縛|ささやき|布石)/.test(n))return 129;return 217}
  var gold={};p.goldSkills.forEach(function(n){gold[n]=1});
  p.cards.forEach(function(c){(c.skills||[]).concat(c.goldSkills||[]).forEach(function(n){n=String(n||'').replace(/◯/g,'○').trim();if(!n)return;var g=gold[n]?'gold':'white';if(by[n]){if(g==='gold'){by[n].grade='gold';by[n].factorEligible=false;by[n].examBonus=1200}return}var sp=guessSp(n,g),ev=guessEval(n,g);var s={name:n,category:aptitude(n)||'その他',priority:g==='gold'?55:45,note:'Ver.3.1追加。未検証値は一般的な同系統スキルからの暫定値。',sp:sp,default:false,tags:[g==='gold'?'金スキル':'追加スキル'],evaluation:ev,verifiedEvaluation:false,estimatedEvaluation:true,aptitudeType:aptitude(n),grade:g,factorEligible:g!=='gold',examBonus:g==='gold'?1200:400};cfg.skillCatalog.push(s);by[n]=s})});
  (cfg.skillCatalog||[]).forEach(function(s){
    if(!s.grade)s.grade='white';
    var g=s.grade==='gold'?'gold':(s.grade==='evolved'?'evolved':'white');
    if(!(Number(s.sp)>0)){s.sp=guessSp(s.name,g);s.estimatedEvaluation=true;s.verifiedEvaluation=false}
    if(!Number.isFinite(Number(s.evaluation))){s.evaluation=guessEval(s.name,g);s.estimatedEvaluation=true;s.verifiedEvaluation=false}
    if(s.factorEligible===undefined)s.factorEligible=g==='white';
    if(s.examBonus===undefined)s.examBonus=g==='gold'?1200:(g==='evolved'?1500:400);
    if(s.estimatedEvaluation&&String(s.note||'').indexOf('暫定')<0)s.note=(s.note?s.note+' ':'')+'未確認値は同系統スキルからの暫定値。';
  });
  cfg.dataVersion='2026-07-29 Ver.3.1 技能試験対応（暫定値を明示）';
})();
